LEGACY_MARKERS = ("vecchia piattaforma", "piattaforma precedente", "CONFLICT_REGISTER")


def _demote_rules_nobody_approved(apps, schema_editor):
    """
    Send every approved or in-force rule without a named approver back to a pre-approval state.

    Eleven rules were in force this way, deliberately, so the engine could be demonstrated before
    the legal review existed. `manage.py rules_pending_review` listed them and the reports said so
    — but a rule in force is a rule that binds somebody, and a list somebody has to remember to
    read is not a control.

    Where they land depends on provenance, which this function assigns at the same time: inherited
    content goes to LEGACY_CANDIDATE, content drafted from a norm goes to DRAFT. Neither is in
    force, so `rules_in_force()` returns nothing until a jurist has walked the chain. Locally,
    `manage.py rules_activate_demonstration` puts them back with an approver label that says in
    words that nobody approved them.
    """
    LegalRule = apps.get_model("rules", "LegalRule")

    for rule in LegalRule.objects.all():
        note = (rule.note or "").lower()
        legacy = any(marker.lower() in note for marker in LEGACY_MARKERS)
        rule.provenance = "legacy_derived" if legacy else "drafted_from_source"

        home = "legacy_candidate" if legacy else "draft"

        if rule.review_status in {"approved", "active"} and not (rule.approved_by_label or "").strip():
            rule.review_status = home
            rule.approved_by = None
            rule.approved_at = None
        elif rule.review_status == "legal_review" and not _sources_are_verified(rule):
            # LEGAL_REVIEW now asserts that somebody opened the sources at the official source and
            # wrote down when. Five rules were sitting in that queue and not one of their sources
            # carried a date, a name or a URL — so a jurist would have been reviewing references on
            # the implicit promise that they had been checked. Back to the start of the chain.
            rule.review_status = home

        rule.save(update_fields=["provenance", "review_status", "approved_by", "approved_at"])


def _sources_are_verified(rule) -> bool:
    """A reference is not a verification: it needs a date, a person, and somewhere to look."""
    sources = list(rule.sources.all())
    return bool(sources) and all(
        s.consulted_on and (s.consulted_by or "").strip() and ((s.url or "").strip() or (s.authority or "").strip())
        for s in sources
    )


